#include <stdlib.h>

char* get_url_for_query(const char* api_url, const char* user_id) {
    if (user_id == NULL || strlen(user_id) == 0) {
        return NULL;
    }

    // Simple sanitization: remove any path traversal characters
    char sanitized_user_id[256];
    strncpy(sanitized_user_id, user_id, sizeof(sanitized_user_id));
    sanitized_user_id[255] = '\0';

    // Remove any occurrence of "../" or "/"
    char* ptr = sanitized_user_id;
    while ((ptr = strstr(ptr, "../")) != NULL) {
        memmove(ptr, ptr + 2, strlen(ptr + 2) + 1);
    }

    // Remove any leading "/"
    if (sanitized_user_id[0] == '/') {
        memmove(sanitized_user_id, sanitized_user_id + 1, strlen(sanitized_user_id) + 1);
    }

    size_t api_len = strlen(api_url);
    size_t user_len = strlen(sanitized_user_id);
    size_t total_len = api_len + user_len + 1; // +1 for the slash

    char* url = (char*)malloc(total_len * sizeof(char));
    if (url == NULL) {
        return NULL;
    }

    snprintf(url, total_len, "%s/%s", api_url, sanitized_user_id);

    return url;
}

